mkdir -p /tmp/contrast-check && cat > /tmp/contrast-check/check.mjs <<'EOF'
import { readFileSync } from 'node:fs';
const css = readFileSync(process.argv[2], 'utf8');
const block = (sel) => { const i = css.indexOf(sel + ' {'); const j = css.indexOf('}', i); return css.slice(i, j); };
const parse = (b) => { const m = {}; for (const [, k, v] of b.matchAll(/--([\w-]+):\s*([^;]+);/g)) m[k] = v.trim(); return m; };
const hex = (h) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16) / 255);
const lin = (c) => (c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4);
const L = (rgb) => { const [r, g, b] = rgb.map(lin); return 0.2126 * r + 0.7152 * g + 0.0722 * b; };
const toRgb = (v, bg) => {
  if (v.startsWith('#')) return hex(v);
  const m = v.match(/rgb\((\d+)\s+(\d+)\s+(\d+)\s*\/\s*([\d.]+)%\)/);
  if (m) { const a = m[4] / 100; const base = [m[1], m[2], m[3]].map((x) => x / 255); return base.map((c, i) => c * a + bg[i] * (1 - a)); }
  throw new Error('unparsed ' + v);
};
const ratio = (a, b) => { const x = L(a), y = L(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); };
const TEXT = [['--primary-foreground','--primary'],['--secondary-foreground','--secondary'],['--destructive-foreground','--destructive'],['--accent-foreground','--accent'],['--muted-foreground','--muted'],['--card-foreground','--card'],['--popover-foreground','--popover'],['--foreground','--background'],['--sidebar-foreground','--sidebar'],['--sidebar-primary-foreground','--sidebar-primary'],['--sidebar-accent-foreground','--sidebar-accent']];
const UI = [['--ring','--background'],['--ring','--card'],['--sidebar-ring','--sidebar']];
for (const [name, sel] of [['light', ':root'], ['dark', ':root.dark']]) {
  const t = parse(block(sel));
  const bgOf = (k) => toRgb(t[k] ?? parse(block(':root'))[k], hex('f6f7fa'));
  console.log('--- ' + name);
  for (const [fg, bg] of TEXT) { const f = toRgb(t[fg.slice(2)], [1,1,1]); const b = toRgb(t[bg.slice(2)], [1,1,1]); const r = ratio(f, b); console.log(`${r >= 4.5 ? 'PASS' : 'FAIL'} text ${fg} on ${bg} ${r.toFixed(2)}`); }
  for (const [fg, bg] of UI) { const bgv = t[bg.slice(2)] ?? parse(block(':root'))[bg.slice(2)]; const f = toRgb(t[fg.slice(2)], [1,1,1]); const b = toRgb(bgv, [1,1,1]); const r = ratio(f, b); console.log(`${r >= 3 ? 'PASS' : 'FAIL'} ui ${fg} on ${bg} ${r.toFixed(2)}`); }
}
EOF
cd D:/Repos/angular-jig && node /tmp/contrast-check/check.mjs src/styles.css

